// Fisher-Yates shuffle: randomize order when page loads
function shuffleArray(arr) {
    var a = arr.slice();
    for (var j = a.length - 1; j > 0; j--) {
        var k = Math.floor(Math.random() * (j + 1));
        var t = a[j];
        a[j] = a[k];
        a[k] = t;
    }
    return a;
}
words = shuffleArray(words);

var part,
i = 0,
offset = 0,
len = words.length,
forwards = true,
skip_count = 0,
skip_delay = 15,
speed = 70;

var wordflick = function () {
    setInterval(function () {
        if (forwards) {
            if (offset >= words[i].length) {
                ++skip_count;
                if (skip_count == skip_delay) {
                    forwards = false;
                    skip_count = 0;
                }
            }
        }
        else {
            if (offset == 0) {
                forwards = true;
                i++;
                offset = 0;
                if (i >= len) {
                    i = 0;
                }
            }
        }
        part = words[i].substr(0, offset);
        if (skip_count == 0) {
            if (forwards) {
                offset++;
            }
            else {
                offset--;
            }
        }
        $('.word').text(part);
    }, speed);
};

$(document).ready(function () {
    wordflick();
});

$(document).ready(function() {
    var rollingBall = $('#rolling-ball');
    var targetImage = $('#questionmark-target');
    var section = $('.what-is-makerspace');
    var hasAnimated = false;
    var animationInProgress = false;

    // Target coordinates on the original 1920x1080 image
    var targetCoordX = 1673;
    var targetCoordY = 963;
    var originalImageWidth = 1920;
    var originalImageHeight = 1080;

    // Function to calculate and return the target position
    function getTargetPosition() {
        var sectionOffset = section.offset();
        var targetOffset = targetImage.offset();
        var currentImageWidth = targetImage.width();
        var currentImageHeight = targetImage.height();

        // Calculate scale factor based on current image size vs original
        var scaleX = currentImageWidth / originalImageWidth;
        var scaleY = currentImageHeight / originalImageHeight;

        // Calculate the scaled target position within the image
        var scaledTargetX = targetCoordX * scaleX;
        var scaledTargetY = targetCoordY * scaleY;

        // Calculate end position relative to section
        var endX = targetOffset.left + scaledTargetX - (rollingBall.width() / 2) - sectionOffset.left;
        var endY = targetOffset.top + scaledTargetY - (rollingBall.height() / 2) - sectionOffset.top;

        return { x: endX, y: endY };
    }

    // Function to snap ball to correct position on resize
    function snapBallToPosition() {
        if (hasAnimated && !animationInProgress) {
            var pos = getTargetPosition();
            rollingBall.css({
                'left': pos.x + 'px',
                'top': pos.y + 'px'
            });
        }
    }

    function animateRollingBall() {
        if (hasAnimated || animationInProgress) return;

        var sectionOffset = section.offset();
        var sectionHeight = section.outerHeight();
        var scrollTop = $(window).scrollTop();
        var windowHeight = $(window).height();

        // Check if section is in view (at least 30% visible)
        var sectionTop = sectionOffset.top;
        var sectionBottom = sectionTop + sectionHeight;
        var viewportBottom = scrollTop + windowHeight;

        if (viewportBottom > sectionTop + (sectionHeight * 0.3) && scrollTop < sectionBottom) {
            animationInProgress = true;

            var pos = getTargetPosition();
            var endX = pos.x;
            var endY = pos.y;

            // Start position (off-screen left, same Y as end)
            var startX = -100;
            var startY = endY;

            // Calculate distance for rotation
            var distance = endX - startX;
            var ballCircumference = Math.PI * rollingBall.width();
            var rotations = distance / ballCircumference;
            var totalRotation = rotations * 360;

            // Set initial position
            rollingBall.css({
                'left': startX + 'px',
                'top': startY + 'px',
                'transform': 'translateX(0) rotate(0deg)',
                'opacity': '1'
            });

            // Animate the ball rolling
            $({progress: 0}).animate({progress: 1}, {
                duration: 2000,
                easing: 'easeOutQuad',
                step: function(progress) {
                    var currentX = startX + (distance * progress);
                    var currentRotation = totalRotation * progress;
                    rollingBall.css({
                        'left': currentX + 'px',
                        'transform': 'rotate(' + currentRotation + 'deg)'
                    });
                },
                complete: function() {
                    hasAnimated = true;
                    animationInProgress = false;
                }
            });
        }
    }

    // Add easing function if not available
    if (!$.easing.easeOutQuad) {
        $.easing.easeOutQuad = function(x, t, b, c, d) {
            return -c *(t/=d)*(t-2) + b;
        };
    }

    // Listen for scroll events
    $(window).on('scroll', function() {
        animateRollingBall();
    });

    // Listen for window resize to snap ball to new position
    $(window).on('resize', function() {
        snapBallToPosition();
    });

    // Bounce animation variables
    var isBouncing = false;
    var bounceTimeout = null;

    // Click handler for bounce animation
    rollingBall.on('click', function(e) {
        e.preventDefault();
        e.stopPropagation();

        // Don't start bouncing if already bouncing or if roll animation hasn't completed
        if (isBouncing || !hasAnimated || animationInProgress) return;

        isBouncing = true;
        var baseY = parseFloat(rollingBall.css('top'));
        var currentRotation = 0;
        var bounceCount = 0;
        var maxBounces = 8 + Math.floor(Math.random() * 5); // 8-12 bounces
        var bounceHeight = 40 + Math.random() * 30; // Initial bounce height 40-70px
        var dampening = 0.7 + Math.random() * 0.15; // How much bounce reduces each time

        function doBounce() {
            if (bounceCount >= maxBounces) {
                // Animation complete, snap back to base position
                rollingBall.css({
                    'top': baseY + 'px',
                    'transform': 'rotate(' + currentRotation + 'deg)'
                });
                isBouncing = false;
                return;
            }

            // Add randomness to each bounce
            var thisHeight = bounceHeight * Math.pow(dampening, bounceCount);
            thisHeight += (Math.random() - 0.5) * 10; // Add ±5px randomness
            var duration = 150 + Math.random() * 50; // 150-200ms per half-bounce

            // Random rotation per bounce
            var rotationChange = (Math.random() - 0.5) * 30; // ±15 degrees

            // Bounce up
            $({progress: 0}).animate({progress: 1}, {
                duration: duration,
                easing: 'easeOutQuad',
                step: function(progress) {
                    var y = baseY - (thisHeight * Math.sin(progress * Math.PI));
                    var rot = currentRotation + (rotationChange * progress);
                    rollingBall.css({
                        'top': y + 'px',
                        'transform': 'rotate(' + rot + 'deg)'
                    });
                },
                complete: function() {
                    currentRotation += rotationChange;
                    bounceCount++;
                    // Small delay between bounces for more natural feel
                    bounceTimeout = setTimeout(doBounce, 20 + Math.random() * 30);
                }
            });
        }

        doBounce();
    });

    // Also check on page load in case section is already visible
    setTimeout(animateRollingBall, 500);
});

