      max-width: 60%;
      margin: 0 auto;
      display: block;
    }
  }

  /* Rolling ball animation styles */
  .what-is-makerspace {
    position: relative;
    overflow: hidden;
  }

  .rolling-ball {
    position: absolute;
    width: 105px;
    height: 105px;
    z-index: 10;
    pointer-events: auto;
    cursor: pointer;
    transform: translateX(-100px);
    transition: none;
  }

  .rolling-ball img {
    width: 100%;
    height: 100%;
    object-fit: contain;
  }

  @media (max-width: 768px) {
    .rolling-ball {
      width: 50px;
      height: 50px;
    }
  }

  /* Tighten spacing between "How our makerspace works" title and content */
  .about-2 .title {
    margin-bottom: 20px;
  }
